import {Quaternion,Euler} from 'three';
import {SkeletalPoseProgram,SkeletalPoseTrack,captureSkeletalPosePage} from './sequence-state.js';
import {SequencePoseOwnership} from './sequence-pose-ownership.js';
import {blendSequencePoses} from './sequence-pose-blending.js';
import {blendIndexedPoses} from './sequence-indexed-transforms.js';

// Programs/bindings are weak; active per-bone samples retain only current leases.
export class SequencePosePlayback{
 constructor(mesh){this.mesh=mesh;this.entries=new Map();this.presentedBones=new Map();this.watchedBones=new Map();this.external=new Map();this.programs=new WeakMap();this.bindings=new WeakMap();this.emptyGroup={};this.ownership=new SequencePoseOwnership();this.work={programsCompiled:0,keysValidated:0,poseRowsValidated:0,layoutsPrepared:0,bindingsCreated:0,bindingsRevalidated:0,samples:0,matrixRootsUpdated:0,batches:0,batchTargets:0,baselineCaptures:0,baselineRows:0,restorations:0,restoredBones:0,queries:0,queryRowsCopied:0};}
 capture(id,names){const {pose,rows,created}=this.ownership.capture(id,this.mesh(id),names);if(created)this.work.baselineCaptures++;this.work.baselineRows+=rows;return pose;}
 set(id,track,time,immediate=false,boneName){
  let previous=this.entries.get(id),entry;
  if(boneName===undefined){entry=previous?.track===track?previous:{track};entry.time=time;this.prepare(id,entry);if(immediate)this.apply(id,entry);this.entries.set(id,entry);return;}
  if(!previous?.slots){previous={slots:new Map(),tracks:new WeakMap(),time};this.entries.set(id,previous);}entry=previous.tracks.get(track);if(!entry){entry={track};previous.tracks.set(track,entry);}entry.time=previous.time=time;this.prepare(id,entry);if(immediate)this.apply(id,{...entry,names:new Set([boneName])});previous.slots.set(boneName,entry);
 }
 prepare(id,entry){
  if(!entry)return;const group=this.mesh(id);
  if(!entry.binding||entry.group!==group){
   if(entry.track.importedPose){entry.group=group;entry.binding=entry.track.importedPose.binding(group);this.work.bindingsRevalidated++;}else{let program=this.programs.get(entry.track.keys);if(!program){program=new SkeletalPoseProgram(entry.track.keys);this.programs.set(entry.track.keys,program);this.work.programsCompiled++;this.work.keysValidated+=program.keys.length;this.work.poseRowsValidated+=program.poseRows;this.work.layoutsPrepared+=program.layoutCount;}
   const key=group||this.emptyGroup;let bindings=this.bindings.get(key);if(!bindings){bindings=new WeakMap();this.bindings.set(key,bindings);}let binding=bindings.get(program);
   if(!binding){binding=new SkeletalPoseTrack(group,program,{time:entry.time});bindings.set(program,binding);this.work.bindingsCreated++;}
   else {binding.rebind(entry.time);this.work.bindingsRevalidated++;}
   entry.group=group;entry.binding=binding;}
  }
  entry.binding.prepare(entry.time);return entry;
 }
 setLayers(id,layers,bone,components=false){let actor=this.entries.get(id);if(!actor?.slots){actor={slots:new Map(),tracks:new WeakMap()};this.entries.set(id,actor);}actor.time=layers[0].time;actor.slots.set(bone,{layers,components,time:actor.time});}
 prepareBlends(items){const plans=new Map(),outputs=[];for(const {id,name,entry}of items){let tracks=plans.get(id);if(!tracks){tracks=new Map();plans.set(id,tracks);}const rows=[];let bone,group;for(const layer of entry.layers){let times=tracks.get(layer.track);if(!times){times=new Map();tracks.set(layer.track,times);}let plan=times.get(layer.time);if(!plan){plan=this.prepare(id,{track:layer.track,time:layer.time});plan.binding.validateBinding(plan.time);plan.bones=new Map(plan.binding.signature.names.map((name,i)=>[name,plan.binding.bones[i]]));times.set(layer.time,plan);}const current=plan.bones.get(name);if(!current||bone&&bone!==current)throw Error('혼합 골격 뼈의 수명이 바뀌었어요: '+name);bone=current;group=plan.group;this.ownership.touch(id,[bone]);rows.push({owner:layer.owner,mix:layer.mix,weight:layer.weight,pose:plan.binding.sampleBone(layer.time,name,{bone,weight:layer.track.poseWeight??1,basis:bone=>this.ownership.basis(id,bone)})});}this.rememberBones(id,[bone]);outputs.push({bone,group,pose:entry.components?blendIndexedPoses(rows,this.external.get(id)?.group===group&&!this.external.get(id)?.source?.controlled?this.external.get(id)?.rows.get(bone)??this.ownership.basis(id,bone):this.ownership.basis(id,bone)):blendSequencePoses(rows)});}return outputs;}
 updateMatrices(groups){for(const group of groups){let covered=false;for(let p=group.parent;p;p=p.parent)if(groups.has(p)){covered=true;break;}if(!covered){group.updateWorldMatrix(true,true);this.work.matrixRootsUpdated++;}}}
 apply(id,entry,updateMatrices=true){entry.binding.validateBinding(entry.time);const bones=entry.names?entry.binding.bones.filter((bone,i)=>entry.names.has(entry.binding.signature.names[i])):entry.binding.bones;this.ownership.touch(id,bones);this.rememberBones(id,bones);entry.binding.sample(entry.time,{updateMatrices:false,boneNames:entry.names,weight:entry.track.poseWeight??1,basis:bone=>this.ownership.basis(id,bone),validated:true});this.work.samples++;if(updateMatrices&&entry.group)this.updateMatrices(new Set([entry.group]));}
 sample(id,entry=this.entries.get(id)){if(entry?.slots){this.sampleAll(value=>value===id);return;}if(this.prepare(id,entry))this.apply(id,entry);}
 sampleAll(accept=()=>true,matrixGroups){
  const prepared=[],blended=[];
  for(const [id,actor]of this.entries)if(accept(id)){
   if(!actor.slots){prepared.push({id,entry:this.prepare(id,actor)});continue;}
   const grouped=new Map();for(const [name,entry]of actor.slots){if(entry.layers){blended.push({id,name,entry});continue;}this.prepare(id,entry);let times=grouped.get(entry.track);if(!times){times=new Map();grouped.set(entry.track,times);}let sample=times.get(entry.time);if(!sample){sample={...entry,names:new Set()};times.set(entry.time,sample);prepared.push({id,entry:sample});}sample.names.add(name);}
  }
  if(!prepared.length&&!blended.length)return;const mixed=this.prepareBlends(blended);for(const {id,entry}of prepared)this.apply(id,entry,false);const groups=new Set(prepared.map(e=>e.entry.group).filter(Boolean));for(const {bone,group,pose}of mixed){bone.position.fromArray(pose.position);bone.quaternion.fromArray(pose.quaternion);bone.scale.fromArray(pose.scale);if(group)groups.add(group);}if(mixed.length){this.work.blendedBones=(this.work.blendedBones||0)+mixed.length;this.work.blendLayerSamples=(this.work.blendLayerSamples||0)+blended.reduce((n,e)=>n+e.entry.layers.length,0);}if(matrixGroups)for(const group of groups)matrixGroups.add(group);else this.updateMatrices(groups);this.work.batches++;this.work.batchTargets+=prepared.length+mixed.length;
 }
 restore(id,pose,name,updateMatrices=true,retain=false,watch){const result=this.ownership.restore(id,pose,this.mesh(id),name,updateMatrices);if(!result.accepted)return;if(result.first)this.work.restorations++;this.work.restoredBones+=result.bones;if(name instanceof Set)for(const bone of name)this.clear(id,bone,retain,watch?.has(bone));else this.clear(id,name,retain,watch);}
 batch(changes){const groups=new Set(),ids=new Set(),restores=new Map();for(const change of changes){if(change.clear){this.clear(change.id,change.bone,change.retain,change.watch);continue;}if(change.baseline){let tokens=restores.get(change.id);if(!tokens){tokens=new Map();restores.set(change.id,tokens);}let names=tokens.get(change.baseline);if(!names){names=new Set();names.retain=false;names.watch=new Set();tokens.set(change.baseline,names);}names.add(change.bone);names.retain||=change.retain;if(change.watch)names.watch.add(change.bone);}else{if(change.layers)this.setLayers(change.id,change.layers,change.bone,change.components);else this.set(change.id,change.track,change.time,false,change.bone);ids.add(change.id);}}for(const[id,tokens]of restores)for(const[token,names]of tokens){const group=this.mesh(id),before=this.work.restoredBones;this.restore(id,token,names,false,names.retain,names.watch);if(this.work.restoredBones!==before&&group)groups.add(group);}this.sampleAll(id=>ids.has(id),groups);this.updateMatrices(groups);}
 rememberBones(id,bones){let rows=this.presentedBones.get(id);if(!rows){rows=new Map();this.presentedBones.set(id,rows);}let watched=this.watchedBones.get(id);if(!watched){watched=new Map();this.watchedBones.set(id,watched);}for(const bone of bones){rows.set(bone.name,bone);watched.set(bone.name,new WeakRef(bone));}}
 withExternal(id,source,run){
  const actor=this.entries.get(id);if(!actor){const watched=this.watchedBones.get(id);if(!this.ownership.baselines.has(id)||!watched?.size){this.external.delete(id);return run();}let saved=this.external.get(id);if(saved?.source!==source||saved.group!==this.mesh(id)){saved={source,group:this.mesh(id),rows:new Map()};this.external.set(id,saved);}const result=run(),live=new Set();for(const reference of watched.values()){const bone=reference.deref();if(!bone)continue;let root=bone;while(root&&root!==saved.group&&(!root.userData?.objectId||root.userData.objectId===saved.group.userData.objectId))root=root.parent;if(root!==saved.group)continue;live.add(bone);let value=saved.rows.get(bone);if(!value){value={position:[],quaternion:[],scale:[]};saved.rows.set(bone,value);}bone.position.toArray(value.position);bone.quaternion.toArray(value.quaternion);bone.scale.toArray(value.scale);}for(const bone of saved.rows.keys())if(!live.has(bone))saved.rows.delete(bone);return result;}const group=this.mesh(id);let saved=this.external.get(id);if(saved?.source!==source||saved.group!==group){saved={source,group,rows:new Map()};this.external.set(id,saved);}const active=[],known=new Set(this.presentedBones.get(id)?.values());for(const bone of saved.rows.keys())if(!known.has(bone))saved.rows.delete(bone);for(const [name,bone]of this.presentedBones.get(id)||[]){if(actor.slots&&!actor.slots.has(name))continue;const value=saved.rows.get(bone)||this.ownership.basis(id,bone);if(!value)continue;bone.position.fromArray(value.position);bone.quaternion.fromArray(value.quaternion);bone.scale.fromArray(value.scale);active.push(bone);}let succeeded=false;try{const result=run();for(const bone of active){let value=saved.rows.get(bone);if(!value){value={position:[],quaternion:[],scale:[]};saved.rows.set(bone,value);}bone.position.toArray(value.position);bone.quaternion.toArray(value.quaternion);bone.scale.toArray(value.scale);}succeeded=true;return result;}finally{if(!succeeded)this.sample(id);}
 }
 underlying(id,source,node,property){const actor=this.entries.get(id);if(!actor||actor.slots&&!actor.slots.has(node?.name))return;const value=this.external.get(id)?.source===source?this.external.get(id).rows.get(node):null;const pose=value||this.ownership.basis(id,node);if(property==='rotation'&&pose?.quaternion){const angles=new Euler().setFromQuaternion(new Quaternion().fromArray(pose.quaternion),node.rotation.order);return [angles.x,angles.y,angles.z];}return pose?.[property]?.slice();}
 presentExternal(id,source){const saved=this.external.get(id);if(saved&&saved.source===source&&saved.group===this.mesh(id)){for(const [bone,value]of saved.rows){let root=bone;while(root&&root!==saved.group&&(!root.userData?.objectId||root.userData.objectId===saved.group.userData.objectId))root=root.parent;if(root!==saved.group)continue;bone.position.fromArray(value.position);bone.quaternion.fromArray(value.quaternion);bone.scale.fromArray(value.scale);}this.sample(id);saved.group?.updateWorldMatrix(true,true);}else this.sample(id);if(!this.entries.has(id))this.external.delete(id);}
 clear(id,name,retain=false,watch=false){if(name!==undefined&&!watch){this.watchedBones.get(id)?.delete(name);if(!this.watchedBones.get(id)?.size)this.watchedBones.delete(id);}const actor=this.entries.get(id);if(name!==undefined&&actor?.slots){actor.slots.delete(name);this.presentedBones.get(id)?.delete(name);if(actor.slots.size)return;}this.entries.delete(id);this.presentedBones.delete(id);if(!retain){this.ownership.clear(id);this.watchedBones.delete(id);}}
 inspect(id,options){const page=captureSkeletalPosePage(this.mesh(id),options),entry=this.entries.get(id),names=entry?.slots?entry.slots:new Set(entry?.binding?.signature.names||[]);this.work.queries++;this.work.queryRowsCopied+=page.bones.length;return {actor:id,controlled:!!entry,time:entry?.time??null,controlledBoneCount:names.size,controlledBones:page.bones.filter(b=>names.has(b.bone)).map(b=>b.bone),...page,sampling:{...this.work,activeTargets:this.entries.size,scope:'Owned playback preparation/sample/query counts; no whole-frame FPS or heap measurement.'}};}
 dispose(){this.entries.clear();this.presentedBones.clear();this.watchedBones.clear();this.external.clear();this.programs=new WeakMap();this.bindings=new WeakMap();this.ownership.dispose();}
}
